137	static int32_t hci_packet_complete(const uint8_t* buf, uint16_t buf_len)
138	{
139	    uint16_t payload_len = 0;
140	    const uint8_t type = buf[0];
141	    uint8_t header_len = sizeof(type);
142	    const uint8_t* hdr = &buf[sizeof(type)];
143	
144	    switch (type) {
145	    case BT_HCI_H4_CMD: {
146	        const struct bt_hci_cmd_hdr* cmd = (const struct bt_hci_cmd_hdr*)hdr;
147	
148	        if (buf_len < header_len + BT_HCI_CMD_HDR_SIZE) {
149	            return 0;
150	        }
151	
152	        /* Parameter Total Length */
153	        payload_len = cmd->param_len;
154	        header_len += BT_HCI_CMD_HDR_SIZE;
155	        break;
156	    }
157	    case BT_HCI_H4_ACL: {
158	        const struct bt_hci_acl_hdr* acl = (const struct bt_hci_acl_hdr*)hdr;
159	
160	        if (buf_len < header_len + BT_HCI_ACL_HDR_SIZE) {
161	            return 0;
162	        }
163	
164	        /* Data Total Length */
165	        payload_len = sys_le16_to_cpu(acl->len);
166	        header_len += BT_HCI_ACL_HDR_SIZE;
167	        break;
168	    }
169	    case BT_HCI_H4_SCO: {
170	        const struct bt_hci_sco_hdr* sco = (const struct bt_hci_sco_hdr*)hdr;
171	
172	        if (buf_len < header_len + BT_HCI_SCO_HDR_SIZE) {
173	            return 0;
174	        }
175	
176	        /* Data_Total_Length */
177	        payload_len = sco->len;
178	        header_len += BT_HCI_SCO_HDR_SIZE;
179	        break;
180	    }
181	    case BT_HCI_H4_EVT: {
182	        const struct bt_hci_evt_hdr* evt = (const struct bt_hci_evt_hdr*)hdr;
183	
184	        if (buf_len < header_len + BT_HCI_EVT_HDR_SIZE) {
185	            return 0;
186	        }
187	
188	        /* Parameter Total Length */
189	        payload_len = evt->len;
190	        header_len += BT_HCI_EVT_HDR_SIZE;
191	        break;
192	    }
193	    case BT_HCI_H4_ISO: {
194	        const struct bt_hci_iso_hdr* iso = (const struct bt_hci_iso_hdr*)hdr;
195	
196	        if (buf_len < header_len + BT_HCI_ISO_HDR_SIZE) {
197	            return 0;
198	        }
199	
200	        /* ISO_Data_Load_Length parameter */
201	        payload_len = bt_iso_hdr_len(sys_le16_to_cpu(iso->len));
202	        header_len += BT_HCI_ISO_HDR_SIZE;
203	        break;
204	    }
205	    /* If no valid packet type found */
206	    default:
207	        BT_LOGE("H4: Unknown packet type 0x%02x", type);
208	        return -1;
209	    }
210	
211	    /* Request more data */
212	    if (buf_len < header_len + payload_len) {
213	        return 0;
214	    }
215	
216	    return (int32_t)header_len + payload_len;
217	}
