314	static void hci_poll_recv(service_poll_t* poll, int revent, void* userdata)
315	{
316	    (void)poll;
317	    (void)userdata;
318	
319	    if (revent & (POLL_ERROR | POLL_DISCONNECT))
320	        hci_remove_recv(NULL);
321	
322	    if (revent & POLL_READABLE)
323	        bt_sal_hci_transport_recv();
