124	    case BT_HCI_H4_ISO:
125	        if (IS_ENABLED(CONFIG_BT_ISO)) {
126	            return bt_buf_get_rx(BT_BUF_ISO_IN, K_FOREVER);
127	        }
128	        break;
129	    default:
130	        BT_LOGE("RX unknown packet type: %u", buf[0]);
131	        break;
132	    }
133	
134	    return NULL;
135	}
136	
137	static int32_t hci_packet_complete(const uint8_t* buf, uint16_t buf_len)
138	{
139	    uint16_t payload_len = 0;
140	    const uint8_t type = buf[0];
141	    uint8_t header_len = sizeof(type);
142	    const uint8_t* hdr = &buf[sizeof(type)];
143	
144	    switch (type) {
145	    case BT_HCI_H4_CMD: {
146	        const struct bt_hci_cmd_hdr* cmd = (const struct bt_hci_cmd_hdr*)hdr;
147	
148	        if (buf_len < header_len + BT_HCI_CMD_HDR_SIZE) {
149	            return 0;
150	        }
151	
152	        /* Parameter Total Length */
153	        payload_len = cmd->param_len;
154	        header_len += BT_HCI_CMD_HDR_SIZE;
155	        break;
156	    }
157	    case BT_HCI_H4_ACL: {
158	        const struct bt_hci_acl_hdr* acl = (const struct bt_hci_acl_hdr*)hdr;
159	
160	        if (buf_len < header_len + BT_HCI_ACL_HDR_SIZE) {
161	            return 0;
162	        }
163	
164	        /* Data Total Length */
165	        payload_len = sys_le16_to_cpu(acl->len);
166	        header_len += BT_HCI_ACL_HDR_SIZE;
167	        break;
168	    }
169	    case BT_HCI_H4_SCO: {
170	        const struct bt_hci_sco_hdr* sco = (const struct bt_hci_sco_hdr*)hdr;
171	
172	        if (buf_len < header_len + BT_HCI_SCO_HDR_SIZE) {
173	            return 0;
174	        }
175	
176	        /* Data_Total_Length */
177	        payload_len = sco->len;
178	        header_len += BT_HCI_SCO_HDR_SIZE;
179	        break;
180	    }
181	    case BT_HCI_H4_EVT: {
182	        const struct bt_hci_evt_hdr* evt = (const struct bt_hci_evt_hdr*)hdr;
183	
184	        if (buf_len < header_len + BT_HCI_EVT_HDR_SIZE) {
185	            return 0;
186	        }
187	
188	        /* Parameter Total Length */
189	        payload_len = evt->len;
190	        header_len += BT_HCI_EVT_HDR_SIZE;
191	        break;
192	    }
193	    case BT_HCI_H4_ISO: {
194	        const struct bt_hci_iso_hdr* iso = (const struct bt_hci_iso_hdr*)hdr;
195	
196	        if (buf_len < header_len + BT_HCI_ISO_HDR_SIZE) {
197	            return 0;
198	        }
199	
200	        /* ISO_Data_Load_Length parameter */
201	        payload_len = bt_iso_hdr_len(sys_le16_to_cpu(iso->len));
202	        header_len += BT_HCI_ISO_HDR_SIZE;
203	        break;
204	    }
205	    /* If no valid packet type found */
206	    default:
207	        BT_LOGE("H4: Unknown packet type 0x%02x", type);
208	        return -1;
209	    }
210	
211	    /* Request more data */
212	    if (buf_len < header_len + payload_len) {
213	        return 0;
214	    }
215	
216	    return (int32_t)header_len + payload_len;
217	}
218	
219	static void bt_sal_hci_transport_recv(void)
220	{
221	    struct h4_data* h4 = bt_dev->data;
222	    static uint8_t frame[1026];
223	    struct net_buf* buf;
224	    size_t buf_tailroom;
225	    size_t buf_add_len;
226	    ssize_t len;
227	    const uint8_t* frame_start = frame;
228	    static ssize_t frame_size = 0;
229	
230	    len = read(h4->fd, frame + frame_size, sizeof(frame) - frame_size);
231	    if (len < 0) {
232	        BT_LOGE("Reading hci failed, errno %d", errno);
233	        close(h4->fd);
234	        h4->fd = -1;
235	        return;
236	    }
237	
238	    frame_size += len;
239	
240	    while (frame_size > 0) {
241	        const uint8_t* buf_add;
242	        const uint8_t packet_type = frame_start[0];
243	        const int32_t decoded_len = hci_packet_complete(frame_start, frame_size);
244	
245	        if (decoded_len == -1) {
246	            BT_LOGE("HCI Packet type is invalid, length could not be decoded");
247	            frame_size = 0; /* Drop buffer */
248	            break;
249	        }
250	
251	        if (decoded_len == 0) {
252	            if (frame_size == sizeof(frame)) {
253	                BT_LOGE("HCI Packet is too big for frame");
254	                frame_size = 0; /* Drop buffer */
255	                break;
256	            }
257	            if (frame_start != frame) {
258	                memmove(frame, frame_start, frame_size);
259	            }
260	            /* Read more */
261	            break;
262	        }
263	
264	        buf_add = frame_start + sizeof(packet_type);
265	        buf_add_len = decoded_len - sizeof(packet_type);
266	
267	        buf = get_rx(frame_start);
268	
269	        frame_size -= decoded_len;
270	        frame_start += decoded_len;
271	
272	        if (!buf) {
273	            BT_LOGD("Discard adv report due to insufficient buf");
274	            continue;
275	        }
276	
277	        buf_tailroom = net_buf_tailroom(buf);
278	        if (buf_tailroom < buf_add_len) {
279	            BT_LOGE("Not enough space in buffer %zu/%zu", buf_add_len,
280	                buf_tailroom);
281	            net_buf_unref(buf);
282	            continue;
283	        }
284	
285	        net_buf_add_mem(buf, buf_add, buf_add_len);
286	
287	        h4_data_dump("BT RX", packet_type, buf->data, buf_add_len);
288	        h4->recv(bt_dev, buf, h4->hci_data);
289	    }
290	}
