237	static ssize_t uart_bth4_read(FAR struct file *filep,
238	                              FAR char *buffer,
239	                              size_t buflen)
240	{
241	  FAR struct inode *inode = filep->f_inode;
242	  FAR struct uart_bth4_s *dev = inode->i_private;
243	  irqstate_t flags;
244	  ssize_t nread;
245	
246	  flags = spin_lock_irqsave(&dev->lock);
247	
248	  for (; ; )
249	    {
250	      nread = circbuf_read(&dev->circbuf, buffer, buflen);
251	      if (nread != 0 || (filep->f_oflags & O_NONBLOCK))
252	        {
253	          break;
254	        }
255	
256	      while (circbuf_is_empty(&dev->circbuf))
257	        {
258	          spin_unlock_irqrestore(&dev->lock, flags);
259	          nxsem_wait_uninterruptible(&dev->recvsem);
260	          flags = spin_lock_irqsave(&dev->lock);
261	        }
262	    }
263	
264	  spin_unlock_irqrestore(&dev->lock, flags);
265	  return nread;
266	}
267	
268	static ssize_t uart_bth4_write(FAR struct file *filep,
269	                               FAR const char *buffer,
270	                               size_t buflen)
271	{
272	  FAR struct inode *inode = filep->f_inode;
273	  FAR struct uart_bth4_s *dev = inode->i_private;
274	  FAR union bt_hdr_u *hdr;
275	  enum bt_buf_type_e type;
276	  size_t reserved;
277	  uint8_t *data;
278	  size_t pktlen;
279	  size_t hdrlen;
280	  int ret;
281	
282	  ret = nxmutex_lock(&dev->sendlock);
283	  if (ret < 0)
284	    {
285	      return ret;
395	  pollevent_t eventset = 0;
396	  irqstate_t flags;
397	  int ret = 0;
398	  int i;
399	
400	  flags = spin_lock_irqsave_nopreempt(&dev->lock);
401	
402	  if (setup)
403	    {
404	      for (i = 0; i < CONFIG_UART_BTH4_NPOLLWAITERS; i++)
405	        {
406	          /* Find an available slot */
407	
408	          if (!dev->fds[i])
409	            {
410	              /* Bind the poll structure and this slot */
411	
412	              dev->fds[i] = fds;
413	              fds->priv   = &dev->fds[i];
414	              break;
415	            }
416	        }
417	
418	      if (i >= CONFIG_UART_BTH4_NPOLLWAITERS)
419	        {
420	          fds->priv = NULL;
421	          ret = -EBUSY;
422	        }
423	
424	      if (!circbuf_is_empty(&dev->circbuf))
425	        {
426	          eventset |= POLLIN;
427	        }
428	
429	      eventset |= POLLOUT;
430	
431	      poll_notify(&fds, 1, eventset);
432	    }
433	  else if (fds->priv != NULL)
434	    {
435	      for (i = 0; i < CONFIG_UART_BTH4_NPOLLWAITERS; i++)
436	        {
437	          if (fds == dev->fds[i])
438	            {
439	              dev->fds[i] = NULL;
440	              fds->priv = NULL;
441	              break;
442	            }
443	        }
444	    }
445	
250	  uint16_t opcode;
251	
252	  if (len < H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s) + 4 ||
253	      data[0] != H4_EVT)
254	    {
255	      return;
256	    }
257	
258	  if (data[1] == BT_HCI_EVT_CMD_COMPLETE && data[2] >= 4)
259	    {
260	      opcode = sf32lb52_bt_get_le16(&data[4]);
261	      if (opcode == BT_HCI_OP_RESET && data[6] != SF32LB52_HCI_STATUS_SUCCESS)
262	        {
263	          data[6] = SF32LB52_HCI_STATUS_SUCCESS;
264	        }
265	    }
266	  else if (data[1] == BT_HCI_EVT_CMD_STATUS && data[2] >= 4)
267	    {
268	      opcode = sf32lb52_bt_get_le16(&data[5]);
269	      if (opcode == BT_HCI_OP_RESET && data[3] != SF32LB52_HCI_STATUS_SUCCESS)
270	        {
271	          data[3] = SF32LB52_HCI_STATUS_SUCCESS;
272	        }
273	    }
274	}
275	
276	static int sf32lb52_bt_forward_packet(struct sf32lb52_bt_priv_s *priv,
277	                                      uint8_t *data, size_t len)
278	{
279	  enum bt_buf_type_e type;
280	  int ret;
281	
282	  if (len <= H4_HEADER_SIZE)
283	    {
284	      return -EINVAL;
285	    }
286	
287	  switch (data[0])
288	    {
289	      case H4_EVT:
290	        #if SF32LB52_BT_NORMALIZE_RESET_STATUS
291	          sf32lb52_bt_normalize_event(data, len);
292	        #endif
293	        type = BT_EVT;
294	        break;
295	
296	      case H4_ACL:
297	        type = BT_ACL_IN;
298	        break;
299	
300	      case H4_ISO:
301	        type = BT_ISO_IN;
302	        break;
303	
304	      default:
305	        return -EINVAL;
306	    }
307	
308	  ret = bt_netdev_receive(&priv->drv,
309	                          type,
310	                          (void *)&data[H4_HEADER_SIZE],
311	                          len - H4_HEADER_SIZE);
312	  if (ret < 0)
313	    {
314	      wlerr("Failed to receive HCI packet: %d\n", ret);
315	    }
316	
317	  return ret;
318	}
319	
320	static int sf32lb52_bt_synth_cmd_complete(struct sf32lb52_bt_priv_s *priv,
321	                                          uint16_t opcode,
322	                                          const uint8_t *return_params,
323	                                          size_t return_len)
324	{
325	  uint8_t event[H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s) + 3 +
326	                SF32LB52_HCI_MAX_CMD_COMPLETE_RPLEN];
327	  size_t payload_len;
328	
329	  if (return_len > SF32LB52_HCI_MAX_CMD_COMPLETE_RPLEN)
330	    {
331	      return -E2BIG;
332	    }
333	
334	  payload_len = 3 + return_len;
335	  event[0] = H4_EVT;
336	  event[1] = BT_HCI_EVT_CMD_COMPLETE;
337	  event[2] = payload_len;
338	  event[3] = 1;
339	  sf32lb52_bt_put_le16(&event[4], opcode);
340	  if (return_len > 0)
341	    {
342	      memcpy(&event[6], return_params, return_len);
343	    }
344	
345	  return sf32lb52_bt_forward_packet(priv, event,
346	                                    H4_HEADER_SIZE +
347	                                    sizeof(struct bt_hci_evt_hdr_s) +
348	                                    payload_len);
