276	static int sf32lb52_bt_forward_packet(struct sf32lb52_bt_priv_s *priv,
277	                                      uint8_t *data, size_t len)
278	{
279	  enum bt_buf_type_e type;
280	  int ret;
281	
282	  if (len <= H4_HEADER_SIZE)
283	    {
284	      return -EINVAL;
285	    }
286	
287	  switch (data[0])
288	    {
289	      case H4_EVT:
290	        #if SF32LB52_BT_NORMALIZE_RESET_STATUS
291	          sf32lb52_bt_normalize_event(data, len);
292	        #endif
293	        type = BT_EVT;
294	        break;
295	
296	      case H4_ACL:
297	        type = BT_ACL_IN;
298	        break;
299	
300	      case H4_ISO:
301	        type = BT_ISO_IN;
302	        break;
303	
304	      default:
305	        return -EINVAL;
306	    }
307	
308	  ret = bt_netdev_receive(&priv->drv,
309	                          type,
310	                          (void *)&data[H4_HEADER_SIZE],
311	                          len - H4_HEADER_SIZE);
312	  if (ret < 0)
313	    {
314	      wlerr("Failed to receive HCI packet: %d\n", ret);
315	    }
316	
317	  return ret;
318	}
