320	static int sf32lb52_bt_synth_cmd_complete(struct sf32lb52_bt_priv_s *priv,
321	                                          uint16_t opcode,
322	                                          const uint8_t *return_params,
323	                                          size_t return_len)
324	{
325	  uint8_t event[H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s) + 3 +
326	                SF32LB52_HCI_MAX_CMD_COMPLETE_RPLEN];
327	  size_t payload_len;
328	
329	  if (return_len > SF32LB52_HCI_MAX_CMD_COMPLETE_RPLEN)
330	    {
331	      return -E2BIG;
332	    }
333	
334	  payload_len = 3 + return_len;
335	  event[0] = H4_EVT;
336	  event[1] = BT_HCI_EVT_CMD_COMPLETE;
337	  event[2] = payload_len;
338	  event[3] = 1;
339	  sf32lb52_bt_put_le16(&event[4], opcode);
340	  if (return_len > 0)
341	    {
342	      memcpy(&event[6], return_params, return_len);
343	    }
344	
345	  return sf32lb52_bt_forward_packet(priv, event,
346	                                    H4_HEADER_SIZE +
347	                                    sizeof(struct bt_hci_evt_hdr_s) +
348	                                    payload_len);
349	}
