109	static struct net_buf* get_rx(const uint8_t* buf)
110	{
111	    bool discardable = false;
112	    k_timeout_t timeout = K_FOREVER;
113	
114	    switch (buf[0]) {
115	    case BT_HCI_H4_EVT:
116	        if (buf[1] == BT_HCI_EVT_LE_META_EVENT && (buf[3] == BT_HCI_EVT_LE_ADVERTISING_REPORT)) {
117	            discardable = true;
118	            timeout = K_NO_WAIT;
119	        }
120	
121	        return bt_buf_get_evt(buf[1], discardable, timeout);
122	    case BT_HCI_H4_ACL:
123	        return bt_buf_get_rx(BT_BUF_ACL_IN, K_FOREVER);
124	    case BT_HCI_H4_ISO:
125	        if (IS_ENABLED(CONFIG_BT_ISO)) {
126	            return bt_buf_get_rx(BT_BUF_ISO_IN, K_FOREVER);
127	        }
128	        break;
129	    default:
130	        BT_LOGE("RX unknown packet type: %u", buf[0]);
131	        break;
132	    }
133	
134	    return NULL;
135	}
