268	static ssize_t uart_bth4_write(FAR struct file *filep,
269	                               FAR const char *buffer,
270	                               size_t buflen)
271	{
272	  FAR struct inode *inode = filep->f_inode;
273	  FAR struct uart_bth4_s *dev = inode->i_private;
274	  FAR union bt_hdr_u *hdr;
275	  enum bt_buf_type_e type;
276	  size_t reserved;
277	  uint8_t *data;
278	  size_t pktlen;
279	  size_t hdrlen;
280	  int ret;
281	
282	  ret = nxmutex_lock(&dev->sendlock);
283	  if (ret < 0)
284	    {
285	      return ret;
395	  pollevent_t eventset = 0;
396	  irqstate_t flags;
397	  int ret = 0;
398	  int i;
399	
400	  flags = spin_lock_irqsave_nopreempt(&dev->lock);
401	
402	  if (setup)
403	    {
404	      for (i = 0; i < CONFIG_UART_BTH4_NPOLLWAITERS; i++)
405	        {
406	          /* Find an available slot */
407	
408	          if (!dev->fds[i])
409	            {
410	              /* Bind the poll structure and this slot */
411	
412	              dev->fds[i] = fds;
413	              fds->priv   = &dev->fds[i];
414	              break;
415	            }
416	        }
417	
418	      if (i >= CONFIG_UART_BTH4_NPOLLWAITERS)
419	        {
420	          fds->priv = NULL;
421	          ret = -EBUSY;
422	        }
423	
424	      if (!circbuf_is_empty(&dev->circbuf))
425	        {
426	          eventset |= POLLIN;
427	        }
428	
429	      eventset |= POLLOUT;
430	
431	      poll_notify(&fds, 1, eventset);
432	    }
433	  else if (fds->priv != NULL)
434	    {
435	      for (i = 0; i < CONFIG_UART_BTH4_NPOLLWAITERS; i++)
436	        {
437	          if (fds == dev->fds[i])
438	            {
439	              dev->fds[i] = NULL;
440	              fds->priv = NULL;
441	              break;
442	            }
443	        }
444	    }
445	
250	  uint16_t opcode;
251	
252	  if (len < H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s) + 4 ||
253	      data[0] != H4_EVT)
254	    {
255	      return;
256	    }
257	
258	  if (data[1] == BT_HCI_EVT_CMD_COMPLETE && data[2] >= 4)
259	    {
260	      opcode = sf32lb52_bt_get_le16(&data[4]);
261	      if (opcode == BT_HCI_OP_RESET && data[6] != SF32LB52_HCI_STATUS_SUCCESS)
262	        {
263	          data[6] = SF32LB52_HCI_STATUS_SUCCESS;
264	        }
265	    }
266	  else if (data[1] == BT_HCI_EVT_CMD_STATUS && data[2] >= 4)
267	    {
268	      opcode = sf32lb52_bt_get_le16(&data[5]);
269	      if (opcode == BT_HCI_OP_RESET && data[3] != SF32LB52_HCI_STATUS_SUCCESS)
270	        {
271	          data[3] = SF32LB52_HCI_STATUS_SUCCESS;
272	        }
273	    }
274	}
