351	static int sf32lb52_bt_synth_status_complete(struct sf32lb52_bt_priv_s *priv,
352	                                             uint16_t opcode)
353	{
354	  const uint8_t status = SF32LB52_HCI_STATUS_SUCCESS;
355	
356	  return sf32lb52_bt_synth_cmd_complete(priv, opcode, &status,
357	                                        sizeof(status));
358	}
359	
360	static bool sf32lb52_bt_emulate_cmd(struct sf32lb52_bt_priv_s *priv,
361	                                    uint16_t opcode, int *ret)
362	{
363	  uint8_t params[SF32LB52_HCI_MAX_CMD_COMPLETE_RPLEN];
364	
365	  switch (opcode)
515	
516	  while (priv->rxlen > 0)
517	    {
518	      packet_len = sf32lb52_bt_h4_packet_len(priv->rxbuf, priv->rxlen);
519	      if (packet_len == 0)
520	        {
521	          break;
522	        }
523	
524	      if (packet_len < 0)
525	        {
526	          syslog(LOG_WARNING,
527	                 "sf32lb52 bth4 drop invalid h4 type=%02x pending=%lu\n",
528	                 priv->rxbuf[0],
529	                 (unsigned long)priv->rxlen);
530	          memmove(priv->rxbuf, &priv->rxbuf[1], priv->rxlen - 1);
531	          priv->rxlen--;
532	          ret = -EINVAL;
533	          continue;
534	        }
535	
536	      if ((size_t)packet_len > priv->rxlen)
537	        {
538	          break;
539	        }
540	
541	      ret = sf32lb52_bt_forward_packet(priv, priv->rxbuf,
542	                   (size_t)packet_len);
543	
544	      priv->rxlen -= (size_t)packet_len;
545	      if (priv->rxlen > 0)
546	        {
547	          memmove(priv->rxbuf,
548	                  &priv->rxbuf[packet_len],
549	                  priv->rxlen);
550	        }
