   138	static int32_t hci_packet_complete(const uint8_t* buf, uint16_t buf_len,
   139	    int32_t* expected_len)
   140	{
   141	    uint16_t payload_len = 0;
   142	    const uint8_t type = buf[0];
   143	    uint8_t header_len = sizeof(type);
   144	    const uint8_t* hdr = &buf[sizeof(type)];
   145	
   146	    *expected_len = 0;
   147	
   148	    switch (type) {
   149	    case BT_HCI_H4_CMD: {
   150	        const struct bt_hci_cmd_hdr* cmd = (const struct bt_hci_cmd_hdr*)hdr;
   151	
   152	        if (buf_len < header_len + BT_HCI_CMD_HDR_SIZE) {
   153	            return 0;
   154	        }
   155	
   156	        /* Parameter Total Length */
   157	        payload_len = cmd->param_len;
   158	        header_len += BT_HCI_CMD_HDR_SIZE;
   159	        break;
   160	    }
   161	    case BT_HCI_H4_ACL: {
   162	        const struct bt_hci_acl_hdr* acl = (const struct bt_hci_acl_hdr*)hdr;
   163	
   164	        if (buf_len < header_len + BT_HCI_ACL_HDR_SIZE) {
   165	            return 0;
   166	        }
   167	
   168	        /* Data Total Length */
   169	        payload_len = sys_le16_to_cpu(acl->len);
   170	        header_len += BT_HCI_ACL_HDR_SIZE;
   171	        break;
   172	    }
   173	    case BT_HCI_H4_SCO: {
   174	        const struct bt_hci_sco_hdr* sco = (const struct bt_hci_sco_hdr*)hdr;
   175	
   176	        if (buf_len < header_len + BT_HCI_SCO_HDR_SIZE) {
   177	            return 0;
   178	        }
   179	
   180	        /* Data_Total_Length */
   181	        payload_len = sco->len;
   182	        header_len += BT_HCI_SCO_HDR_SIZE;
   183	        break;
   184	    }
   185	    case BT_HCI_H4_EVT: {
   186	        const struct bt_hci_evt_hdr* evt = (const struct bt_hci_evt_hdr*)hdr;
   187	
   188	        if (buf_len < header_len + BT_HCI_EVT_HDR_SIZE) {
   189	            return 0;
   190	        }
   191	
   192	        /* Parameter Total Length */
   193	        payload_len = evt->len;
   194	        header_len += BT_HCI_EVT_HDR_SIZE;
   195	        break;
   196	    }
   197	    case BT_HCI_H4_ISO: {
   198	        const struct bt_hci_iso_hdr* iso = (const struct bt_hci_iso_hdr*)hdr;
   199	
   200	        if (buf_len < header_len + BT_HCI_ISO_HDR_SIZE) {
   201	            return 0;
   202	        }
   203	
   204	        /* ISO_Data_Load_Length parameter */
   205	        payload_len = bt_iso_hdr_len(sys_le16_to_cpu(iso->len));
   206	        header_len += BT_HCI_ISO_HDR_SIZE;
   207	        break;
   208	    }
   209	    /* If no valid packet type found */
   210	    default:
   211	        BT_LOGE("H4: Unknown packet type 0x%02x", type);
   212	        *expected_len = -1;
   213	        return -1;
   214	    }
   215	
   216	    *expected_len = (int32_t)header_len + payload_len;
   217	
   218	    /* Request more data */
   219	    if (buf_len < header_len + payload_len) {
   220	        return 0;
   221	    }
   222	
   223	    return (int32_t)header_len + payload_len;
   224	}
   225	
   226	static void bt_sal_hci_transport_recv(void)
   227	{
   228	    struct h4_data* h4 = bt_dev->data;
   229	    static uint8_t frame[1026];
   230	    struct net_buf* buf;
   231	    size_t buf_tailroom;
   232	    size_t buf_add_len;
   233	    ssize_t len;
   234	    int read_errno;
   235	    const uint8_t* frame_start = frame;
   236	    static ssize_t frame_size = 0;
   237	
   238	    len = read(h4->fd, frame + frame_size, sizeof(frame) - frame_size);
   239	    read_errno = errno;
   240	    if (len < 0) {
   241	        syslog(LOG_ERR,
   242	            "zblue h4 diag: read fd=%d ret=%zd errno=%d frame_size=%zd closing=1\n",
   243	            h4->fd, len, read_errno, frame_size);
   244	        close(h4->fd);
   245	        h4->fd = -1;
   246	        return;
   247	    }
   248	
   249	    if (len == 0) {
   250	        syslog(LOG_ERR, "zblue h4 diag: read fd=%d ret=0 frame_size=%zd\n",
   251	            h4->fd, frame_size);
   252	    }
   253	
   254	    frame_size += len;
   255	
   256	    while (frame_size > 0) {
   257	        const uint8_t* buf_add;
   258	        const uint8_t packet_type = frame_start[0];
   259	        int32_t expected_len;
   260	        const int32_t decoded_len = hci_packet_complete(frame_start, frame_size,
   261	            &expected_len);
   262	
   263	        if (decoded_len == -1) {
   264	            syslog(LOG_ERR,
   265	                "zblue h4 diag: drop reason=invalid_type type=0x%02x frame_size=%zd expected=%ld\n",
   266	                packet_type, frame_size, (long)expected_len);
   267	            BT_LOGE("HCI Packet type is invalid, length could not be decoded");
   268	            frame_size = 0; /* Drop buffer */
   269	            break;
   270	        }
   271	
   272	        if (decoded_len == 0) {
   273	            if (frame_size == sizeof(frame)) {
   274	                syslog(LOG_ERR,
   275	                    "zblue h4 diag: drop reason=frame_limit type=0x%02x frame_size=%zd expected=%ld\n",
   276	                    packet_type, frame_size, (long)expected_len);
   277	                BT_LOGE("HCI Packet is too big for frame");
   278	                frame_size = 0; /* Drop buffer */
   279	                break;
   280	            }
   281	            if (frame_start != frame) {
   282	                memmove(frame, frame_start, frame_size);
   283	            }
   284	            /* Read more */
   285	            break;
   286	        }
   287	
   288	        buf_add = frame_start + sizeof(packet_type);
   289	        buf_add_len = decoded_len - sizeof(packet_type);
   290	
   291	        buf = get_rx(frame_start);
   292	
   293	        frame_size -= decoded_len;
   294	        frame_start += decoded_len;
   295	
   296	        if (!buf) {
   297	            syslog(LOG_ERR,
   298	                "zblue h4 diag: drop reason=no_rx_buffer type=0x%02x frame_size=%ld expected=%ld\n",
   299	                packet_type, (long)decoded_len, (long)expected_len);
   300	            BT_LOGD("Discard adv report due to insufficient buf");
   301	            continue;
   302	        }
   303	
   304	        buf_tailroom = net_buf_tailroom(buf);
   305	        if (buf_tailroom < buf_add_len) {
   306	            syslog(LOG_ERR,
   307	                "zblue h4 diag: drop reason=tailroom type=0x%02x frame_size=%ld expected=%ld\n",
   308	                packet_type, (long)decoded_len, (long)expected_len);
   309	            BT_LOGE("Not enough space in buffer %zu/%zu", buf_add_len,
   310	                buf_tailroom);
   311	            net_buf_unref(buf);
   312	            continue;
   313	        }
   314	
   315	        net_buf_add_mem(buf, buf_add, buf_add_len);
   316	
   317	        h4_data_dump("BT RX", packet_type, buf->data, buf_add_len);
   318	        h4->recv(bt_dev, buf, h4->hci_data);
   319	    }
   320	}
   338	
   339	    BT_LOGD("%s", __func__);
   340	    service_loop_remove_poll(hci_handle);
   341	    hci_handle = NULL;
   342	}
   343	
   344	static void hci_poll_recv(service_poll_t* poll, int revent, void* userdata)
   345	{
   346	    (void)poll;
   347	    (void)userdata;
   348	
   349	    if (revent & (POLL_ERROR | POLL_DISCONNECT)) {
   350	        syslog(LOG_ERR, "zblue h4 diag: poll fd=%d revents=0x%x\n",
   351	            ((struct h4_data*)bt_dev->data)->fd, revent);
   352	        hci_remove_recv(NULL);
   353	    }
   354	
   355	    if (revent & POLL_READABLE)
   356	        bt_sal_hci_transport_recv();
