   132	
   133	static int uart_bth4_receive(FAR struct bt_driver_s *drv,
   134	                             enum bt_buf_type_e type,
   135	                             FAR void *buffer, size_t buflen)
   136	{
   137	  FAR struct uart_bth4_s *dev = drv->priv;
   138	  int ret = buflen;
   139	  irqstate_t flags;
   140	  uint8_t htype;
   141	  uint8_t diag_htype;
   142	  size_t used;
   143	  size_t space;
   144	  size_t required;
   145	  uint32_t drops = 0;
   146	  bool rx_full = false;
   147	
   148	  flags = spin_lock_irqsave_nopreempt(&dev->lock);
   149	
   150	  used = circbuf_used(&dev->circbuf);
   151	  space = circbuf_space(&dev->circbuf);
   152	  required = buflen + H4_HEADER_SIZE;
   153	  if (type == BT_EVT)
   154	    {
   155	      diag_htype = H4_EVT;
   156	    }
   157	  else if (type == BT_ACL_IN)
   158	    {
   159	      diag_htype = H4_ACL;
   160	    }
   161	  else if (type == BT_ISO_IN)
   162	    {
   163	      diag_htype = H4_ISO;
   164	    }
   165	  else
   166	    {
   167	      diag_htype = 0;
   168	    }
   169	
   170	  if (space >= required)
   171	    {
   172	      if (type == BT_EVT)
   173	        {
   174	          htype = H4_EVT;
   175	        }
   176	      else if (type == BT_ACL_IN)
   177	        {
   178	          htype = H4_ACL;
   179	        }
   180	      else if (type == BT_ISO_IN)
   181	        {
   182	          htype = H4_ISO;
   183	        }
   184	      else
   185	        {
   186	          ret = -EINVAL;
   187	        }
   188	
   189	      if (ret >= 0)
   190	        {
   191	          circbuf_write(&dev->circbuf, &htype, H4_HEADER_SIZE);
   192	          circbuf_write(&dev->circbuf, buffer, buflen);
   193	          uart_bth4_pollnotify(dev, POLLIN);
   194	        }
   195	    }
   196	  else
   197	    {
   198	      ret = -ENOMEM;
   199	      dev->rx_full_drops++;
   200	      drops = dev->rx_full_drops;
   201	      rx_full = true;
   202	    }
   203	
   204	  spin_unlock_irqrestore_nopreempt(&dev->lock, flags);
   205	
   206	  if (rx_full)
   207	    {
   208	      syslog(LOG_ERR,
   209	             "uart_bth4 diag: rx full type=%u payload=%zu required=%zu "
   210	             "used=%zu space=%zu drops=%lu\n",
   211	             diag_htype, buflen, required, used, space,
   212	             (unsigned long)drops);
   213	    }
   214	
   215	  return ret;
   216	}
