   139	static int probe_wait_for_ble_startup(uint64_t target_ms)
   140	{
   141	  struct timespec now;
   142	  uint64_t uptime_ms;
   143	  uint64_t remaining_ms;
   144	  uint64_t sleep_ms;
   145	  bool delay_logged = false;
   146	
   147	  for (;;)
   148	    {
   149	      if (clock_gettime(CLOCK_MONOTONIC, &now) < 0)
   150	        {
   151	          printf("openvela_ble_probe: failed to read system uptime\n");
   152	          return -1;
   153	        }
   154	
   155	      uptime_ms = (uint64_t)now.tv_sec * 1000u +
   156	                  (uint64_t)now.tv_nsec / 1000000u;
   157	      if (uptime_ms >= target_ms)
   158	        {
   159	          if (!delay_logged)
   160	            {
   161	              printf("openvela_ble_probe: BLE startup target=%llu ms "
   162	                     "already satisfied\n",
   163	                     (unsigned long long)target_ms);
   164	            }
   165	
   166	          return 0;
   167	        }
   168	
   169	      remaining_ms = target_ms - uptime_ms;
   170	      if (!delay_logged)
   171	        {
   172	          printf("openvela_ble_probe: delaying BLE start %llu ms "
   173	                 "for platform readiness (target=%llu ms)\n",
   174	                 (unsigned long long)remaining_ms,
   175	                 (unsigned long long)target_ms);
   176	          delay_logged = true;
   177	        }
   178	
   179	      sleep_ms = remaining_ms > 100u ? 100u : remaining_ms;
   180	      usleep((useconds_t)(sleep_ms * 1000u));
   181	    }
   182	}
