   348	             (unsigned long)id_or_seq);
   349	      status = probe_notify(srv_handle, response, 5);
   350	      printf("openvela_ble_probe: throughput START_ACK status=%d\n", status);
   351	      return;
   352	    }
   353	  else if (length >= 1 && value[0] == 0x11)
   354	    {
   355	      if (length < 5)
   356	        {
   357	          printf("openvela_ble_probe: short DATA length=%u\n", length);
   358	          return;
   359	        }
   360	
   361	      if (!g_throughput.active)
