   795	static int start_advertising(void)
   796	{
   797	  ble_adv_params_t params;
   798	
   799	  if (g_advertiser != NULL)
   800	    {
   801	      return 0;
   802	    }
   803	
   804	  memset(&params, 0, sizeof(params));
   805	  params.adv_type = BT_LE_LEGACY_ADV_IND;
   806	  params.interval = 320;
   807	  params.duration = 0;
   808	  params.channel_map = BT_LE_ADV_CHANNEL_DEFAULT;
   809	  params.filter_policy = BT_LE_ADV_FILTER_WHITE_LIST_FOR_NONE;
   810	
   811	  if (g_adv_data == NULL || g_scan_rsp_data == NULL)
   812	    {
   813	      g_adv_data = advertiser_data_new();
   814	      g_scan_rsp_data = advertiser_data_new();
   815	      if (g_adv_data == NULL || g_scan_rsp_data == NULL)
   816	        {
   817	          printf("openvela_ble_probe: advertiser_data_new failed\n");
   818	          return -1;
   819	        }
   820	
   821	      advertiser_data_set_flags(g_adv_data,
   822	                                BT_AD_FLAG_GENERAL_DISCOVERABLE |
   823	                                BT_AD_FLAG_BREDR_NOT_SUPPORT);
   824	      advertiser_data_set_name(g_scan_rsp_data, "ov_ble_probe");
   825	
   826	      g_adv_payload = advertiser_data_build(g_adv_data,
   827	                                            &g_adv_payload_len);
   828	      g_scan_rsp_payload = advertiser_data_build(g_scan_rsp_data,
   829	                                                 &g_scan_rsp_payload_len);
   830	      if (g_adv_payload == NULL || g_scan_rsp_payload == NULL)
   831	        {
   832	          printf("openvela_ble_probe: advertiser_data_build failed\n");
   833	          return -1;
   834	        }
   835	    }
   836	
   837	  g_advertiser = bt_le_start_advertising(g_instance, &params,
   838	                                         g_adv_payload, g_adv_payload_len,
   839	                                         g_scan_rsp_payload,
   840	                                         g_scan_rsp_payload_len,
   841	                                         &g_advertiser_callbacks);
   842	  if (g_advertiser == NULL)
   843	    {
   844	      printf("openvela_ble_probe: bt_le_start_advertising failed\n");
   845	      return -1;
   846	    }
   847	
   848	  printf("openvela_ble_probe: advertising as ov_ble_probe\n");
   849	  return 0;
   850	}
