   454	static uint16_t probe_rx_written(gatts_handle_t srv_handle,
   455	                                 bt_address_t *addr,
   456	                                 uint16_t attr_handle,
   457	                                 const uint8_t *value,
   458	                                 uint16_t length,
   459	                                 uint16_t offset)
   460	{
   461	  struct probe_rx_slot_s *slot;
   462	
   463	  (void)srv_handle;
   464	  (void)attr_handle;
   465	
   466	  if (offset != 0 || length > PROBE_RX_FRAME_MAX)
   467	    {
   468	      __atomic_fetch_add(&g_rx_drop_invalid, 1, __ATOMIC_RELAXED);
   469	      return 0;
   470	    }
   471	
   472	  if (pthread_mutex_trylock(&g_state_lock) != 0)
   473	    {
   474	      __atomic_fetch_add(&g_rx_drop_lock_busy, 1, __ATOMIC_RELAXED);
   475	      return length;
   476	    }
   477	
   478	  if (g_rx_count >= PROBE_RX_QUEUE_DEPTH)
   479	    {
   480	      pthread_mutex_unlock(&g_state_lock);
   481	      __atomic_fetch_add(&g_rx_drop_full, 1, __ATOMIC_RELAXED);
   482	      return length;
   483	    }
   484	
   485	  slot = &g_rx_queue[g_rx_head];
   486	  memcpy(&slot->addr, addr, sizeof(slot->addr));
   487	  slot->connection_generation = g_connection_generation;
   488	  slot->length = length;
   489	  slot->offset = offset;
   490	  memcpy(slot->value, value, length);
   491	  g_rx_head = (g_rx_head + 1) % PROBE_RX_QUEUE_DEPTH;
   492	  g_rx_count++;
   493	  if (g_rx_count >
   494	      __atomic_load_n(&g_rx_high_water, __ATOMIC_RELAXED))
   495	    {
   496	      __atomic_store_n(&g_rx_high_water, g_rx_count, __ATOMIC_RELAXED);
   497	    }
   498	  pthread_mutex_unlock(&g_state_lock);
   499	
   500	  __atomic_fetch_add(&g_rx_enqueued, 1, __ATOMIC_RELAXED);
   501	  sem_post(&g_rx_sem);
   502	  return length;
   503	}
