   592	static void on_gatts_connected(gatts_handle_t srv_handle, bt_address_t *addr)
   593	{
   594	  (void)srv_handle;
   595	
   596	  pthread_mutex_lock(&g_state_lock);
   597	  g_connection_generation++;
   598	  __atomic_store_n(&g_rx_enqueued, 0, __ATOMIC_RELAXED);
   599	  __atomic_store_n(&g_rx_drop_invalid, 0, __ATOMIC_RELAXED);
   600	  __atomic_store_n(&g_rx_drop_lock_busy, 0, __ATOMIC_RELAXED);
   601	  __atomic_store_n(&g_rx_drop_full, 0, __ATOMIC_RELAXED);
   602	  __atomic_store_n(&g_rx_high_water, 0, __ATOMIC_RELAXED);
   603	  __atomic_store_n(&g_rx_stale, 0, __ATOMIC_RELAXED);
   604	  memcpy(&g_peer_addr, addr, sizeof(g_peer_addr));
   605	  g_notify_enabled = false;
   606	  g_phy_read_requested = false;
   607	  g_phy_update_requested = false;
   608	  g_phy_update_pending = false;
   609	  g_peer_connected = true;
   610	  g_phy_read_pending = true;
   611	  pthread_mutex_unlock(&g_state_lock);
   612	  printf("openvela_ble_probe: GATT client connected\n");
   613	}
