   620	
   621	  pthread_mutex_lock(&g_state_lock);
   622	  g_connection_generation++;
   623	  g_peer_connected = false;
   624	  g_notify_enabled = false;
   625	  g_phy_read_pending = false;
   626	  g_phy_update_pending = false;
   627	  g_phy_read_requested = false;
   628	  g_phy_update_requested = false;
   629	  pthread_mutex_unlock(&g_state_lock);
   630	  sem_post(&g_rx_sem);
