   852	int main(int argc, char *argv[])
   853	{
   854	  bt_address_t peer_addr;
   855	  bt_status_t status;
   856	  uint64_t startup_target_ms;
   857	  uint32_t generation;
   858	  bool do_phy_read;
   859	  bool do_phy_update;
   860	  int ret;
   861	
   862	  if (probe_parse_startup_uptime(argc, argv, &startup_target_ms) < 0)
   863	    {
   864	      return 1;
   865	    }
   866	
   867	  if (probe_wait_for_ble_startup(startup_target_ms) < 0)
   868	    {
   869	      return 1;
   870	    }
   871	
   872	  sem_init(&g_ble_on_sem, 0, 0);
   873	
   874	  g_instance = bluetooth_create_instance();
   875	  if (g_instance == NULL)
   876	    {
   877	      printf("openvela_ble_probe: bluetooth_create_instance failed\n");
   878	      return 1;
   879	    }
   880	
   881	  if (bt_adapter_register_callback(g_instance, &g_adapter_callbacks) == NULL)
   882	    {
   883	      printf("openvela_ble_probe: callback registration failed\n");
   884	      return 1;
   885	    }
   886	
   887	  status = bt_adapter_enable_le(g_instance);
   888	  if (status != BT_STATUS_SUCCESS && status != BT_STATUS_DONE)
   889	    {
   890	      printf("openvela_ble_probe: bt_adapter_enable_le failed:%d\n",
   891	             status);
   892	      return 1;
   893	    }
   894	
   895	  if (bt_adapter_get_state(g_instance) != BT_ADAPTER_STATE_BLE_ON &&
   896	      bt_adapter_get_state(g_instance) != BT_ADAPTER_STATE_ON)
   897	    {
   898	      printf("openvela_ble_probe: waiting for BLE adapter\n");
   899	      sem_wait(&g_ble_on_sem);
   900	    }
   901	
   902	  ret = pthread_mutex_init(&g_state_lock, NULL);
   903	  if (ret != 0)
   904	    {
   905	      printf("openvela_ble_probe: state mutex init failed:%d\n", ret);
   906	      return 1;
   907	    }
   908	
   909	  if (sem_init(&g_rx_sem, 0, 0) < 0)
   910	    {
   911	      printf("openvela_ble_probe: RX semaphore init failed\n");
   912	      return 1;
   913	    }
   914	
   915	  if (init_gatt_service() < 0)
   916	    {
   917	      return 1;
   918	    }
   919	
   920	  ret = pthread_create(&g_communication_thread, NULL,
   921	                       probe_communication_thread, NULL);
   922	  if (ret != 0)
   923	    {
   924	      printf("openvela_ble_probe: communication thread create failed:%d\n",
   925	             ret);
   926	      return 1;
   927	    }
   928	
   929	  printf("openvela_ble_probe: delaying advertising 100 ms after GATT "
   930	         "table setup\n");
   931	  usleep(100000);
   932	
   933	  if (start_advertising() < 0)
   934	    {
   935	      return 1;
   936	    }
   937	
   938	  for (;;)
   939	    {
   940	      usleep(100000);
   941	
   942	      do_phy_read = false;
   943	      do_phy_update = false;
   944	
   945	      pthread_mutex_lock(&g_state_lock);
   946	      generation = g_connection_generation;
   947	      if (g_peer_connected && g_phy_read_pending &&
   948	          !g_phy_read_requested)
   949	        {
   950	          g_phy_read_pending = false;
   951	          g_phy_read_requested = true;
   952	          memcpy(&peer_addr, &g_peer_addr, sizeof(peer_addr));
   953	          do_phy_read = true;
   954	        }
   955	      else if (g_peer_connected && g_phy_update_pending &&
   956	               !g_phy_update_requested)
   957	        {
   958	          g_phy_update_pending = false;
   959	          g_phy_update_requested = true;
   960	          memcpy(&peer_addr, &g_peer_addr, sizeof(peer_addr));
   961	          do_phy_update = true;
   962	        }
   963	      pthread_mutex_unlock(&g_state_lock);
   964	
   965	      if (do_phy_read)
   966	        {
   967	          status = bt_gatts_read_phy(g_service_handle, &peer_addr);
   968	          printf("openvela_ble_probe: PHY read request status=%d\n",
   969	                 status);
   970	
   971	          if (status == BT_STATUS_SUCCESS)
   972	            {
   973	              pthread_mutex_lock(&g_state_lock);
   974	              if (g_peer_connected &&
   975	                  generation == g_connection_generation)
   976	                {
   977	                  g_phy_update_pending = true;
   978	                }
   979	              pthread_mutex_unlock(&g_state_lock);
   980	            }
   981	
   982	          continue;
   983	        }
   984	
   985	      if (do_phy_update)
   986	        {
   987	          status = bt_gatts_update_phy(g_service_handle, &peer_addr,
   988	                                       BT_LE_2M_PHY, BT_LE_2M_PHY);
   989	          printf("openvela_ble_probe: PHY 2M request status=%d\n",
   990	                 status);
   991	        }
   992	    }
   993	}
