    98	static int probe_parse_startup_uptime(int argc, char *argv[],
    99	                                      uint64_t *target_ms)
   100	{
   101	  const char *cursor;
   102	  uint32_t value = 0;
   103	
   104	  if (argc == 1)
   105	    {
   106	      *target_ms = MIN_BLE_STARTUP_UPTIME_MS;
   107	      return 0;
   108	    }
   109	
   110	  if (argc == 2 && argv[1][0] != '\0')
   111	    {
   112	      for (cursor = argv[1]; *cursor != '\0'; cursor++)
   113	        {
   114	          if (*cursor < '0' || *cursor > '9')
   115	            {
   116	              goto invalid;
   117	            }
   118	
   119	          value = value * 10u + (uint32_t)(*cursor - '0');
   120	          if (value > 15000u)
   121	            {
   122	              goto invalid;
   123	            }
   124	        }
   125	
   126	      if (value >= 5000u && value <= 15000u && value % 250u == 0)
   127	        {
   128	          *target_ms = value;
   129	          return 0;
   130	        }
   131	    }
   132	
   133	invalid:
   134	  printf("Usage: openvela_ble_probe "
   135	         "[min_uptime_ms: 5000..15000, step 250]\n");
   136	  return -1;
   137	}
